const unusedParts = `-- name: UnusedParts :many
SELECT p.id FROM calc.part p
WHERE p.organization_id = $1 AND p.id > $2::uuid AND p.created_at < $3
    AND NOT EXISTS (
        SELECT 1 FROM calc.revision_part rp
        JOIN calc.revision r ON r.organization_id = rp.organization_id AND r.id = rp.revision_id
        WHERE rp.organization_id = p.organization_id AND rp.part_id = p.id AND r.status <> 'failed')
ORDER BY p.id
LIMIT $4
FOR UPDATE OF p SKIP LOCKED
`

type UnusedPartsParams struct {
	OrganizationID uuid.UUID
	AfterID        uuid.UUID
	Before         time.Time
	RowLimit       int32
}

func (q *Queries) UnusedParts(ctx context.Context, arg UnusedPartsParams) ([]uuid.UUID, error) {
	rows, err := q.db.Query(ctx, unusedParts,
		arg.OrganizationID,
		arg.AfterID,
		arg.Before,
		arg.RowLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []uuid.UUID
	for rows.Next() {
		var id uuid.UUID
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const upsertPart = `-- name: UpsertPart :one
INSERT INTO calc.part (organization_id, id, input_hash, metric_set, part_range, created_at)
VALUES ($1, $2, $3, $4,
    tstzrange($5::timestamptz, $6::timestamptz, '[)'), $7)
ON CONFLICT (organization_id, input_hash) DO UPDATE SET input_hash = EXCLUDED.input_hash
RETURNING id
`

type UpsertPartParams struct {
	OrganizationID uuid.UUID
	ID             uuid.UUID
	InputHash      []byte
	MetricSet      string
	PartFrom       time.Time
	PartTo         time.Time
	CreatedAt      time.Time
}

func (q *Queries) UpsertPart(ctx context.Context, arg UpsertPartParams) (uuid.UUID, error) {
	row := q.db.QueryRow(ctx, upsertPart,
		arg.OrganizationID,
		arg.ID,
		arg.InputHash,
		arg.MetricSet,
		arg.PartFrom,
		arg.PartTo,
		arg.CreatedAt,
	)
	var id uuid.UUID
	err := row.Scan(&id)
	return id, err
}
